cd ~/.claude/projects && python3 - <<'EOF'
import re,glob,os
files={"-Users-kristinarash-DEV/memory":["feedback_session-history-tracked.md","project_dormant-threads.md","project_memsearch-index-is-destructive.md","project_rtp-cla-course.md"],
"-Users-kristinarash/memory":["project-python-environment.md","project_ai-integration-initiative.md","project_facecomps-practice-simulator.md","project_practice-load-framework.md","user_context.md"]}
for d,fs in files.items():
    names={}
    for p in glob.glob(d+"/*.md"):
        t=open(p).read()
        m=re.search(r'^name:\s*(\S+)',t,re.M)
        if m: names[m.group(1)]=p
    idx=open(d+"/MEMORY.md").read()
    for f in fs:
        t=open(f"{d}/{f}").read()
        fm=t.split('---')[1]
        ok=all(re.search(k,fm,re.M) for k in [r'^name:',r'^description:',r'^\s+type:'])
        links=re.findall(r'\[\[([^\]]+)\]\]',t)
        bad=[l for l in links if l not in names]
        inidx=f"]({f})" in idx
        print(f, "fm_ok",ok,"links",links,"BAD",bad,"indexed",inidx)
    for l in re.findall(r'\]\(([^)]+\.md)\)',idx):
        if not os.path.exists(f"{d}/{l}"): print("INDEX BROKEN",d,l)
EOF

